-- ============================================================
-- AkoraHub - Patch Phase 33 : Suggestions de noms pour Matières Premières
-- À exécuter une seule fois : Supabase Dashboard -> SQL Editor -> New query
--
-- Liste de noms de matières premières (chimiques + ingrédients
-- alimentaires) à choisir dans un sélecteur au moment d'ajouter un
-- produit (lib/presentation/product_management_real/), plutôt que de
-- tout taper à la main. Organisée par pilier + catégorie existants
-- (voir phase10_patch_new_business_units.sql) : Matières Premières (12
-- catégories), Matières Premières Peinture, Anti-Nuisibles. Les
-- ingrédients alimentaires vont dans leur famille chimique avec une note
-- "qualité alimentaire" (convention déjà actée avec l'utilisateur, voir
-- phase10). Rien n'est retiré/désactivé : juste des suggestions, le nom
-- reste librement modifiable au moment de créer le produit.
--
-- Relecture avant exécution (demandée par l'utilisateur) : 11 doublons
-- retirés — même substance listée deux fois (une fois nom simple, une
-- fois variante E-number/cas d'usage), ou carrément le même nom exact
-- rangé dans deux catégories différentes (Sulfate de sodium, STPP,
-- Sulfate d'aluminium).
-- ============================================================

create table if not exists public.raw_material_name_suggestions (
  id uuid primary key default gen_random_uuid(),
  business_unit_slug text not null,
  category_name text not null,
  name text not null,
  note text,
  created_at timestamptz not null default now(),
  unique (business_unit_slug, category_name, name)
);

alter table public.raw_material_name_suggestions enable row level security;

drop policy if exists "raw_material_name_suggestions_staff_only" on public.raw_material_name_suggestions;
create policy "raw_material_name_suggestions_staff_only" on public.raw_material_name_suggestions
  for select using (public.current_role_is_staff());

drop policy if exists "raw_material_name_suggestions_write_admin_only" on public.raw_material_name_suggestions;
create policy "raw_material_name_suggestions_write_admin_only" on public.raw_material_name_suggestions
  for all using (public.current_role_is_admin())
  with check (public.current_role_is_admin());

on conflict (business_unit_slug, category_name, name) do nothing;
